// === Tab: mySketch ===
let N = 32*32*32;
let vfbWide, vfbHigh, fbOldVoxels, fbNewVoxels;
let ffbWide, ffbHigh, fbFaces;
let updateShdr, faceShdr, drawShdr;
let seed;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);

	seed = int(random(1<<31));

	vfbWide = 1024;
	vfbHigh = int(ceil(34*34*34/1024));
	let fbOptions = { format: UNSIGNED_BYTE,
	  	    				  depth: false, antialias: false, density: 1,
					    		  width: vfbWide, height: vfbHigh };
	fbOldVoxels = createFramebuffer( fbOptions );
	fbNewVoxels = createFramebuffer( fbOptions );
	fbOldVoxels.begin();
	background(0,0);
	fbOldVoxels.end();

	ffbWide = 1024;
	ffbHigh = int(ceil(32*32*32*6/1024));
	fbOptions = { format: UNSIGNED_BYTE,
	    				  depth: false, antialias: false, density: 1,
			    		  width: ffbWide, height: ffbHigh };
	fbFaces = createFramebuffer( fbOptions );

	updateShdr = createShader( vsUpdate, fsUpdate );
	faceShdr = createShader( vsUpdate, fsFace );
	drawShdr = createShader( vsDraw, fsDraw );

	camera( 0, 0, 3,  0, 0.1, 0,  0, 1, 0 );
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function draw() {
	let t = frameCount/60.0;
	//t = 0.0;

	fbNewVoxels.begin();
	updateShdr.bindShader();
	updateShdr.setUniform( 'voxels', fbOldVoxels );
	updateShdr.setUniform( 'seed', seed );
	updateShdr.setUniform( 'time', t );
	updateShdr.setUniform( 'origin', [0, 0, 0] );
	updateShdr.bindTextures();
	gl = fbNewVoxels.gl;
	gl.drawArrays( gl.TRIANGLES, 0, 3 );  // a single full-screen triangle
	updateShdr.unbindTextures();
	updateShdr.unbindShader();
	fbNewVoxels.end();

	fbFaces.begin();
	faceShdr.bindShader();
	faceShdr.setUniform( 'voxels', fbNewVoxels );
	faceShdr.bindTextures();
	gl = fbFaces.gl;
	gl.drawArrays( gl.TRIANGLES, 0, 3 );  // a single full-screen triangle
	faceShdr.unbindTextures();
	faceShdr.unbindShader();
	fbFaces.end();

	background(0);
	perspective( PI/3*max(1.0*height/width,1.0), 1.0*width/height, 0.01, 10 );
	orbitControl();
	rotateX( PI*0.5-0.5 );  // orient +z up, +x east, +y south
	rotateZ( TAU*0.04*t );
	noFill();
	stroke(255);
	strokeWeight(0.01);
	box(2, 2, 2);

	gl = this._renderer.GL;
	drawShdr.bindShader();
	drawShdr.setUniform( 'voxels', fbOldVoxels );
	drawShdr.setUniform( 'faces', fbFaces );
	drawShdr.bindTextures();
	gl.enable( gl.CULL_FACE );
	gl.frontFace( gl.CW );
	gl.drawArraysInstanced( gl.TRIANGLE_STRIP, 0, 4, 6*N );
	gl.disable( gl.CULL_FACE );
	drawShdr.unbindTextures();
	drawShdr.unbindShader();

	let temp = fbOldVoxels;
	fbOldVoxels = fbNewVoxels;
	fbNewVoxels = temp;
}

function keyPressed() {
	seed = int(random(1<<31));
}

let vsUpdate = `#version 300 es
precision highp float;
precision highp int;
void main() {
	gl_Position = vec4( 4*ivec2(gl_VertexID&1, gl_VertexID&2)-1, 0., 1. );
}
`;

let fsUpdate = `#version 300 es
precision highp float;
precision highp int;
uniform sampler2D voxels;
uniform int seed;
uniform float time;
uniform vec3 origin;
out vec4 fragColor;
#define TAU 6.28318530178

vec2 rot2( vec2 p, float a ) {
  return cos(a)*p + sin(a)*vec2(-p.y, p.x);
}

// http://www.jcgt.org/published/0009/03/02/
// https://www.shadertoy.com/view/XlGcRh
uvec4 pcg4d( uvec4 v ) {
  v = v * 1664525u + 1013904223u;
  v.x += v.y*v.w;  v.y += v.z*v.x;  v.z += v.x*v.y;  v.w += v.y*v.z;
  v ^= v >> 16u;
  v.x += v.y*v.w;  v.y += v.z*v.x;  v.z += v.x*v.y;  v.w += v.y*v.z;
  return v;
}
vec4 pcg4df( int a, int b, int c, int d ) {
  return vec4((pcg4d( uvec4( a, b, c, d ) ) >> 8)) / float( 1<<24 );
}

// psrdnoise (c) Stefan Gustavson and Ian McEwan,
// ver. 2021-12-02, published under the MIT license:
// https://github.com/stegu/psrdnoise/

vec4 permute(vec4 i) {
     vec4 im = mod(i, 289.0);
     return mod(((im*34.0)+10.0)*im, 289.0);
}

float psrdnoise(vec3 x, vec3 period, float alpha, out vec3 gradient)
{
  const mat3 M = mat3(0.0, 1.0, 1.0, 1.0, 0.0, 1.0,  1.0, 1.0, 0.0);
  const mat3 Mi = mat3(-0.5, 0.5, 0.5, 0.5,-0.5, 0.5, 0.5, 0.5,-0.5);
  vec3 uvw = M * x;
  vec3 i0 = floor(uvw), f0 = fract(uvw);
  vec3 g_ = step(f0.xyx, f0.yzz), l_ = 1.0 - g_;
  vec3 g = vec3(l_.z, g_.xy), l = vec3(l_.xy, g_.z);
  vec3 o1 = min( g, l ), o2 = max( g, l );
  vec3 i1 = i0 + o1, i2 = i0 + o2, i3 = i0 + vec3(1.0);
  vec3 v0 = Mi * i0, v1 = Mi * i1, v2 = Mi * i2, v3 = Mi * i3;
  vec3 x0 = x - v0, x1 = x - v1, x2 = x - v2, x3 = x - v3;
  if(any(greaterThan(period, vec3(0.0)))) {
    vec4 vx = vec4(v0.x, v1.x, v2.x, v3.x);
    vec4 vy = vec4(v0.y, v1.y, v2.y, v3.y);
    vec4 vz = vec4(v0.z, v1.z, v2.z, v3.z);
		if(period.x > 0.0) vx = mod(vx, period.x);
		if(period.y > 0.0) vy = mod(vy, period.y);
		if(period.z > 0.0) vz = mod(vz, period.z);
		i0 = floor(M * vec3(vx.x, vy.x, vz.x) + 0.5);
		i1 = floor(M * vec3(vx.y, vy.y, vz.y) + 0.5);
		i2 = floor(M * vec3(vx.z, vy.z, vz.z) + 0.5);
		i3 = floor(M * vec3(vx.w, vy.w, vz.w) + 0.5);
  }
  vec4 hash = permute( permute( permute( 
              vec4(i0.z, i1.z, i2.z, i3.z ))
            + vec4(i0.y, i1.y, i2.y, i3.y ))
            + vec4(i0.x, i1.x, i2.x, i3.x ));
  vec4 theta = hash * 3.883222077;
  vec4 sz = hash * -0.006920415 + 0.996539792;
  vec4 psi = hash * 0.108705628;
  vec4 Ct = cos(theta), St = sin(theta);
  vec4 sz_prime = sqrt( 1.0 - sz*sz );
  vec4 gx, gy, gz;
  if(alpha != 0.0) {
    vec4 px = Ct * sz_prime, py = St * sz_prime, pz = sz;
    vec4 Sp = sin(psi), Cp = cos(psi), Ctp = St*Sp - Ct*Cp;
    vec4 qx = mix( Ctp*St, Sp, sz), qy = mix(-Ctp*Ct, Cp, sz);
    vec4 qz = -(py*Cp + px*Sp);
    vec4 Sa = vec4(sin(alpha)), Ca = vec4(cos(alpha));
    gx = Ca*px + Sa*qx; gy = Ca*py + Sa*qy; gz = Ca*pz + Sa*qz;
  } else {
    gx = Ct * sz_prime; gy = St * sz_prime; gz = sz;  
  }
  vec3 g0 = vec3(gx.x, gy.x, gz.x), g1 = vec3(gx.y, gy.y, gz.y);
  vec3 g2 = vec3(gx.z, gy.z, gz.z), g3 = vec3(gx.w, gy.w, gz.w);
  vec4 w = 0.5-vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3));
  w = max(w, 0.0); vec4 w2 = w * w, w3 = w2 * w;
  vec4 gdotx = vec4(dot(g0,x0), dot(g1,x1), dot(g2,x2), dot(g3,x3));
  float n = dot(w3, gdotx);
  vec4 dw = -6.0 * w2 * gdotx;
  vec3 dn0 = w3.x * g0 + dw.x * x0;
  vec3 dn1 = w3.y * g1 + dw.y * x1;
  vec3 dn2 = w3.z * g2 + dw.z * x2;
  vec3 dn3 = w3.w * g3 + dw.w * x3;
  gradient = 39.5 * (dn0 + dn1 + dn2 + dn3);
  return 39.5 * n;
}

void main() {
  ivec2 dataRes = textureSize( voxels, 0 );
  int idx = int(gl_FragCoord.y) * dataRes.x + int(gl_FragCoord.x);
  vec4 vd = texelFetch( voxels, ivec2(gl_FragCoord.xy), 0 );
	vec3 p = origin + vec3( idx%34, (idx/34)%34, idx/(34*34) ) - 1.;
	vec3 offs = 1024. * pcg4df( seed, 634, 26, 954 ).xyz;
	offs.z += 0.05*time;
	vec3 grd;
	float n = psrdnoise( 0.027 * p+offs, vec3(0.), time*0.15, grd );
	float a;
	if( p.z > n*16.+16. ) {
	  a = 0.;
	} else {
		offs = 1024. * pcg4df( seed, 261, 284, 475 ).xyz;
  	offs.z -= 0.03*time;
	  n = psrdnoise( 0.037 * p+offs, vec3(0.), time*0.17, grd );
		vd.rgb = vec3(1.)-0.125*(grd+1.);
		a = 1.;
	}

  a = (3.*vd.a+a)/4.;
	if( a < 1./32. ) a = 0.;
	if( a > 31./32. ) a = 1.;
	fragColor = vec4( vd.rgb, a );
}
`;


let fsFace = `#version 300 es
precision highp float;
precision highp int;
uniform sampler2D voxels;
out vec4 fragColor;

bool isBlock( int i ) {
  return texelFetch( voxels, ivec2( i%1024, i/1024 ), 0 ).a == 1.;
}

const int aoLevels[8] = int[](0, 1, 1, 2, 1, 3, 2, 3 );
int computeAO( int mid, int dx, int dy ) {
	int b = (isBlock(mid-dx) ? 1+256 : 0) + (isBlock(mid-dx-dy) ? 2 : 0) +
					(isBlock(mid-dy) ? 4  : 0) + (isBlock(mid+dx-dy) ? 8 : 0) +
					(isBlock(mid+dx) ? 16 : 0) + (isBlock(mid+dx+dy) ? 32 : 0) +
					(isBlock(mid+dy) ? 64 : 0) + (isBlock(mid-dx+dy) ? 128 : 0);
	return aoLevels[ b & 7 ] + 
	      (aoLevels[ (b>>2) & 7 ]<<2) +
				(aoLevels[ (b>>4) & 7 ]<<6) + 
				(aoLevels[ (b>>6) & 7 ]<<4);
}

const int offsets[18] = int[18]( 
	1, -34, -34*34,  -1, 34, -34*34,  // +/- x
	34, 1, -34*34,  -34, -1, -34*34,  // +/- y
	34*34, 1, 34,  -34*34, 1, -34 );  // +/- z
void main() {
  ivec2 dataRes = textureSize( voxels, 0 );
  int faceIdx = int(gl_FragCoord.y) * 1024 + int(gl_FragCoord.x);
	int iFace = faceIdx % 6;
	int iVox = faceIdx / 6;
	ivec3 cubePos = ivec3( iVox&31, (iVox>>5)&31, iVox>>10 ) + 1;
	int voxIdx = (cubePos.z*34+cubePos.y)*34+cubePos.x;
  vec4 vd = texelFetch( voxels, ivec2(voxIdx%1024, voxIdx/1024), 0 );
	if( vd.a == 0. ) {
		fragColor = vec4( vd.rgb, 1. );
		return;
	}
	int iMid = voxIdx + offsets[iFace*3];
	if( texelFetch( voxels, ivec2( iMid%1024, iMid/1024 ), 0 ).a == 1. ) {
		fragColor = vec4( vd.rgb, 1. );
		return;
	}
	int ao = computeAO( iMid, offsets[iFace*3+1], offsets[iFace*3+2] );
  fragColor = vec4( vd.rgb, float(ao)/255. );
}
`;


let vsDraw = `#version 300 es
precision highp float;
precision highp int;
uniform mat4 uModelViewMatrix;
uniform mat4 uNormalMatrix;
uniform mat4 uProjectionMatrix;
uniform sampler2D voxels;
uniform sampler2D faces;
out vec2 uv;
out vec4 vColor;

vec3 hsb2rgb( in vec3 c ) {
   vec3 rgb = clamp(abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),
                            6.0)-3.0)-1.0,  0.0,  1.0 );
   rgb = rgb*rgb*(3.0-2.0*rgb);
   return c.z * mix( vec3(1.0), rgb, c.y);
}

const int vidx[24] = int[]( 
	7, 5, 3, 1,  4, 6, 0, 2,    // +/- x
	6, 7, 2, 3,  5, 4, 1, 0,    // +/- y
	4, 5, 6, 7,  2, 3, 0, 1 );  // +/- z

void main() {
	vec4 f = texelFetch( faces, ivec2(gl_InstanceID%1024, gl_InstanceID/1024), 0 );
	int cornerid = gl_VertexID;
	int iao = int(f.a*255.5);
	// rotate the quad diagonal if needed
	if( (iao>>6)+(iao&3) < ((iao>>4)&3)+((iao>>2)&3) ) 
	  cornerid = (2*cornerid+1)%5;
	float ao = 1.-(float((iao>>(cornerid*2))&3))/4.;
  int iCube = gl_InstanceID / 6;
	ivec3 cubePos = ivec3( iCube&31, (iCube>>5)&31, iCube>>10 );
	int idx = ((cubePos.z+1)*34+(cubePos.y+1))*34+cubePos.x+1;
	vec4 vd = texelFetch( voxels, ivec2( idx&1023, idx>>10 ), 0 );
  int iFace = gl_InstanceID % 6;
  uv = vec2( cornerid&1, (cornerid&2)>>1 );
	int ip = vidx[ iFace*4+cornerid ];
	vec4 vPos = vec4( ip&1, (ip>>1)&1, ip>>2, 1. );
	vPos.xyz = (vPos.xyz-0.5) * vd.a + 0.5;
	vPos.xyz += vec3(cubePos);
	vPos.xyz = vPos.xyz/16.-1.;
	vPos = uModelViewMatrix * vPos;
	if( vd.a < 0.01 ) { vPos.xyz = vec3(0.); vd = vec4(0.); }
  gl_Position = uProjectionMatrix * vPos;
	float u = float(iFace)/6.;
	//float d = pow(clamp((4.5+vPos.z)/2.5, 0., 1.), 1.);
	//vec3 c = hsb2rgb( vec3( u, 0.7, d ) );
	vColor = vec4( vd.rgb * ao, 1. );
	//vColor = vec4( vec3(ao), 1. );
}
`;

let fsDraw = `#version 300 es
precision highp float;
in vec2 uv;
in vec4 vColor;
out vec4 fragColor;

float sdBox( in vec2 p, in vec2 b ) {
  vec2 d = abs(p)-b;
  return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}

void main() {
	fragColor = vColor;
	vec2 luv = abs((uv-0.5)*1.75);
	fragColor.rgb *= 1.-pow(max(luv.x, luv.y), 8.);
	//fragColor.rgb *= step(0., sdBox(uv-0.25, vec2(0.1, 0.2) ));
}
`;

